using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Look up a configuration value by key name.")]
    public static string GetConfigValue(
        [Description("The configuration key to look up (e.g. 'MaxRetries')")] string key)
    {
        var config = AppConfig.Current;
        return config.TryGetValue(key, out var value)
            ? $"{key} = {value}"
            : $"Key '{key}' not found. Available keys: {string.Join(", ", config.Keys)}";
    }

    [McpServerTool, Description("List all available configuration keys.")]
    public static string ListConfigKeys()
    {
        return string.Join("\n", AppConfig.Current.Keys.Order());
    }
}

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(
        UriTemplate = "config://app/settings",
        Name = "Application Settings",
        MimeType = "application/json"),
     Description("Returns the full application configuration as JSON.")]
    public static string GetAllSettings()
    {
        return JsonSerializer.Serialize(AppConfig.Current, AppConfig.JsonOptions);
    }

    [McpServerResource(
        UriTemplate = "config://app/settings/{section}",
        Name = "Configuration Section",
        MimeType = "application/json"),
     Description("Returns configuration values for a specific section (e.g. 'database', 'features').")]
    public static string GetSection(string section)
    {
        var sectionData = AppConfig.Current
            .Where(kv => kv.Key.StartsWith(section, StringComparison.OrdinalIgnoreCase))
            .ToDictionary(kv => kv.Key, kv => kv.Value);

        return sectionData.Count > 0
            ? JsonSerializer.Serialize(sectionData, AppConfig.JsonOptions)
            : JsonSerializer.Serialize(new { error = $"No settings found for section '{section}'" });
    }
}

using System.Text.Json;

public static class AppConfig
{
    public static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

    public static Dictionary<string, string> Current { get; } = new()
    {
        ["database.ConnectionString"] = "Server=db.example.com;Database=AppDb",
        ["database.MaxPoolSize"] = "100",
        ["features.EnableCaching"] = "true",
        ["features.MaintenanceMode"] = "false",
        ["app.MaxRetries"] = "3",
        ["app.TimeoutSeconds"] = "30",
        ["app.Environment"] = "Production",
    };
}

